code='''from collections import defaultdict, deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            for x, y in q:
                comp.append((x, y))
                for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            out.append((color, comp))
    return out

def _lshape(comp):
    rs = [p[0] for p in comp]
    cs = [p[1] for p in comp]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    if r1-r0 < 2 or c1-c0 < 2:
        return False
    # A signal is a pair of full perpendicular arms meeting at a bounding-box corner.
    for rr in (r0, r1):
        for cc in (c0, c1):
            shape = {(rr, y) for y in range(c0, c1+1)} | {(x, cc) for x in range(r0, r1+1)}
            if set(comp) == shape:
                return True
    return False

def _norm(comp):
    r0 = min(r for r, c in comp)
    c0 = min(c for r, c in comp)
    return frozenset((r-r0, c-c0) for r, c in comp)

def _center(comp):
    return (sum(r for r,c in comp)/len(comp), sum(c for r,c in comp)/len(comp))

def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    colors = {}
    for color, comp in comps:
        if _lshape(comp):
            colors.setdefault(color, []).append(comp)
    if not colors:
        return out
    # The longest corner-line is the color key.
    marker_color, marker = max(((color, comp) for color, cs in colors.items() for comp in cs), key=lambda z: len(z[1]))
    mr, mc = _center(marker)
    groups = defaultdict(list)
    for color, comp in comps:
        if color != marker_color and len(comp) > 1:
            groups[_norm(comp)].append((color, comp))
    repeated = [(shape, items) for shape, items in groups.items() if len(items) > 1]
    if repeated:
        # Recolor the farthest instance of the most repeated matching silhouette.
        shape, items = max(repeated, key=lambda x: (len(x[1]), len(x[0])))
        color, chosen = max(items, key=lambda z: abs(_center(z[1])[0]-mr) + abs(_center(z[1])[1]-mc))
    else:
        # A straight arm can also encode the area of the object to be recolored.
        rs = [r for r,c in marker]; cs = [c for r,c in marker]
        arm = max(max(rs)-min(rs)+1, max(cs)-min(cs)+1)
        choices = [(color, comp) for color, comp in comps if color != marker_color and len(comp) == arm]
        if not choices:
            return out
        color, chosen = max(choices, key=lambda z: abs(_center(z[1])[0]-mr) + abs(_center(z[1])[1]-mc))
    for r, c in chosen:
        out[r][c] = marker_color
    return out
'''
